NEW_FILES = {'test_room_necks.py': '"""A room\'s necks: the widest way between every two of its route endpoints (0.256.0, the factory\'s roadmap 284).\n\n`room_necks` asks the factory\'s census of what furnishing costs a route (`docs/findings/furnish_route_cost/\nroute_cost.py` at the factory root) its own question of one room: the largest clearance c joining two endpoints, a\nbody passing where c reaches its radius, two abreast where 2c reaches `two_abreast_width()`. Furnish asks it of a host\nthe rescue moves (`_move`), which may take no width from a pair it leaves under two abreast (`_narrows`). Read against\nthe census before it shipped: 187 pairs in 64 rooms of twelve specs the change leaves alone, every neck the same to the\nmillimetre (the factory\'s patches/dc_desk_move/).\n"""\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nimport agent_contract  # noqa: E402\nimport level_design as L  # noqa: E402\n\nCELL = float(agent_contract.contract()["nav_bake"]["cell_size_m"])\n\n\ndef _room(gap=None):\n    """A 10 m square storey, one room, a door in the south wall and one in the north; with `gap`, a box across the\n    room between them leaving `gap` metres to the east wall\'s inner face."""\n    spec = {\n        "name": "neck_probe", "seed": 7, "footprint_x": 10, "footprint_y": 10, "n_stories": 1, "story_height": 3.0,\n        "wall_thick": 0.3, "floor_thick": 0.3, "default_material": "concrete",\n        "materials": [{"id": "concrete", "acoustic": "Concrete"}],\n        "rooms": [{"id": "hall", "story": 0, "bounds": [-5, -5, 5, 5], "role": "open_floor"}],\n        "ext_walls": [{"story": 0, "wall": "S", "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]},\n                      {"story": 0, "wall": "N", "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]}],\n        "volumes": [], "partitions": [], "stairs": [], "ladders": [], "markers": [],\n    }\n    if gap is not None:\n        inner = 5 - 0.15\n        x1 = inner - gap\n        spec["volumes"].append({"name": "probe_box", "x": (-inner + x1) / 2.0, "y": 0.0, "z": 0.5,\n                                "size_x": x1 + inner, "size_y": 1.0, "size_z": 1.0, "collision": "convex",\n                                "material": "concrete"})\n    return spec, spec["rooms"][0]\n\n\ndef test_a_rooms_neck_is_half_the_narrowest_gap_a_body_must_pass():\n    """The open room: its two doors joined at the clearance just past a door\'s open approach disc -- the wall the door\n    stands in, `_ROUTE_DOOR_IN` plus `_NECK_DOOR_ZONE` off it and a cell on (the first draft of this test asked for the\n    cap, and read 1.598). A box across the room leaving 1.2 m at the east wall: half that, to a cell. The box to the\n    wall: the doors parted, the pair absent."""\n    spec, room = _room()\n    assert [k for k, _l, _x, _y in L.room_route_endpoints(spec, room)] == ["door", "door"]\n    necks = L.room_necks(spec, room)\n    assert list(necks) == [(0, 1)]\n    assert abs(necks[(0, 1)] - (L._ROUTE_DOOR_IN + L._NECK_DOOR_ZONE + CELL / 2.0)) <= CELL, necks\n    spec, room = _room(gap=1.2)\n    neck = L.room_necks(spec, room)[(0, 1)]\n    assert abs(neck - 0.6) <= CELL, neck\n    spec, room = _room(gap=0.0)\n    assert L.room_necks(spec, room) == {}\n\n\ndef test_a_neck_narrowed_counts_only_under_two_abreast():\n    """`_narrows`: a pair left two abreast (a 2.4 m gap, a 1.2 m neck) is not narrowed, however much it lost; one left\n    single file (1.2 m) is; one parted is."""\n    open_ = L.room_necks(*_room())\n    assert not L._narrows(open_, L.room_necks(*_room(gap=2.4)))\n    assert L._narrows(open_, L.room_necks(*_room(gap=1.2)))\n    assert L._narrows(open_, L.room_necks(*_room(gap=0.0)))\n    assert not L._narrows(open_, open_)\n'}
CHANGELOG = '## [0.256.0] - a host no chair fits beside is moved where one does\n\n**The factory\'s roadmap 284.** 0.252.0 seats a host the room left chairless and takes away one no chair fits beside:\n25 hosts, 24 desks and a dining table. Asked whether such a desk should be moved instead of removed, the walker,\n2026-10-21: "yes".\n\n### Changed\n- **A host no chair fits beside moves** (`_move`), still LAST, when the room is furnished, so every piece the room\'s\n  recipe drew stands where it stood and no draw is taken from the room\'s stream: to the nearest spot on the room\'s\n  candidate grid where it clears as `_host` placed it (off the nested rooms, `_seed_clear` with the spread from every\n  other piece), faced as `_host` faces it, and seated as the rescue seats one, from a stream keyed by the new spot. It\n  and its chair keep off the room\'s routes -- the reserved ones, or where the recipe reserves none, the routes\n  `protected_routes` asks of the room for the move -- and it narrows no pair (below). A floor piece only, as all 25\n  were; a host no spot takes still goes.\n- **A moved host narrows no route.** Seated at a spot, it may take no width from any two of the room\'s route endpoints\n  that it leaves under two abreast, nor part two that were joined (`_narrows`). Keeping off a route keeps its length,\n  not its width: without this, the 19 hosts the move stood narrowed nine pairs from two abreast to single file, in two\n  rooms -- landmark_hall_a01\'s curator_band (six) and train_yard_a01\'s dispatch_office (three) -- each desk off the\n  routes and standing where the widest way ran.\n- **`room_necks(spec, room)`, new**: the widest-path neck between every two of a room\'s route endpoints -- the\n  factory\'s census of what furnishing costs a route (its `docs/findings/furnish_route_cost/route_cost.py`) asked of\n  one room, at the bake\'s cell, with its obstacles, its endpoint snapping, its open door-approach disc and its\n  union-find, so what furnish guards and what the census reports are one measure. Read against the census before it\n  shipped: 187 pairs in 64 rooms of twelve specs this change leaves alone, every neck the same to the millimetre.\n- `_seats` takes `keep_off`, the routes a moved host\'s chairs keep off in place of the room\'s reserved ones.\n- **The library refurnished**: 18 hosts back in 17 specs -- 17 desks (239 -> 256) and museum_a01\'s dining table (254\n  -> 255) -- each with its chair; seven still go, every spot on their rooms\' 25-spot grids refused (9 to 19 on a\n  route, 6 to 14 by `_seed_clear`, the rest by the chair or, twice in train_yard_a01\'s dispatch_office, by the guard):\n  airport_terminal_a01\'s customs_office two, bank_branch_a04\'s security_office, bank_job\'s security_room,\n  supermarket_a02\'s manager_suite, train_yard_a01\'s dispatch_office two.\n\n### Tests\n- **test_seated_hosts.py**: "seating a chairless host moves nothing the room drew" lets a host the rescue moves stand\n  elsewhere -- only a host, and only one chairless without the rescue; a new test, office\'s exec_suite and\n  landmark_hall_a01\'s curator_band each move their desk, in its room, with its chair, both off the room\'s routes,\n  narrowing no pair -- failing on 0.255.0 on behaviour (no host moves there).\n- **test_room_necks.py**, new: an open room\'s neck, the gap a box leaves, a pair the box parts; `_narrows` counting\n  only width lost under two abreast. Both fail on 0.255.0 on the missing name (the factory\'s\n  `patches/dc_desk_move/prove_tests_on_0255.out.txt`).\n\n### Measured, kept\n- **The census over the library**, each arm refurnished and sheltered in memory against 0.255.0\'s (the factory\'s\n  `patches/dc_desk_move/arms.py`, its control reproducing the census pair for pair): routes over 10 % 26 -> 26, closed\n  to the bake 5 -> 5, narrowed to single file 151 -> 151, p99 1.107, max 1.308; ten pairs lost width and every one is\n  still two abreast, the narrowest now curator_band\'s at 1.053 m of clearance against two abreast\'s 0.95. The floor\n  share of the 17 rooms a host came back to: 1.9 to 7.5 %, each up 0.2 to 2.1 points.\n- **The arms before the guard**: off the routes only, 19 back and the nine narrowings above; then anywhere `_host`\n  itself would stand it, 21 back and the same nine; then its chair\'s routes relaxed too, 24 back, the same nine and\n  one pair over 10 % (dispatch_office\'s secure_door to its objective, 5.60 -> 6.85 m).\n- **Refuted and kept**: the arms\' first run counted a host as moved or gone only where it stood in the shipped\n  library, and the 25 stand in neither -- "gone 0, moved 0" for every arm, only its host counts seeing them;\n  test_room_necks\'s first draft asked an open room for the clearance cap and read 1.598, the wall a door stands in\n  just past its open disc.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.255.0', 'Deli Counter 0.256.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
